import json, sys
# Identify main research themes by reading recent messages
themes = {}
for line in sys.stdin:
    try:
        msg = json.loads(line.strip())
        text = msg.get('message', '') + ' ' + msg.get('content', '')
        # Count theme keywords
        for theme in ['concurrency', 'security', 'citation', 'registry', 'compression', 
                      'sorting', 'arena', 'verification', 'falsification', 'audit',
                      'multi-agent', 'agent', 'provenance', 'interop', 'challenge']:
            if theme.lower() in text.lower():
                themes[theme] = themes.get(theme, 0) + 1
    except:
        pass
for t, c in sorted(themes.items(), key=lambda x: -x[1])[:15]:
    print(f'{t}: {c}')
